import{_ as a,o as t,c as n,ag as i}from"./chunks/framework.BGkQCay2.js";const h=JSON.parse('{"title":"Comptime Pipeline Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/comptime-pipeline.md","filePath":"architecture/comptime-pipeline.md"}'),s={name:"architecture/comptime-pipeline.md"};function r(o,e,l,c,d,p){return t(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="comptime-pipeline-architecture" tabindex="-1">Comptime Pipeline Architecture <a class="header-anchor" href="#comptime-pipeline-architecture" aria-label="Permalink to &quot;Comptime Pipeline Architecture&quot;">​</a></h1><p>Vex comptime is a semantic HIR stage shared by the compiler, diagnostics, lint, and LSP. LLVM is a consumer of the result, not the evaluator and not the source of compile-time truth.</p><h2 id="end-to-end-flow" tabindex="-1">End-to-end flow <a class="header-anchor" href="#end-to-end-flow" aria-label="Permalink to &quot;End-to-end flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source + target + tracked build inputs</span></span>
<span class="line"><span>  -&gt; parse and lower source HIR</span></span>
<span class="line"><span>  -&gt; discover eager module generators</span></span>
<span class="line"><span>  -&gt; canonical CTFE under one metered expansion session</span></span>
<span class="line"><span>  -&gt; seal source + generated declaration snapshot</span></span>
<span class="line"><span>  -&gt; inference, contracts, ownership, borrow and layout validation</span></span>
<span class="line"><span>  -&gt; effect classification and typed staging</span></span>
<span class="line"><span>       -&gt; Known(value)</span></span>
<span class="line"><span>       -&gt; Residual(typed HIR)</span></span>
<span class="line"><span>       -&gt; Error(diagnostic)</span></span>
<span class="line"><span>  -&gt; compiler / diagnostics / lint / LSP consume the same snapshot</span></span>
<span class="line"><span>  -&gt; normal monomorphization, Valence/VUMM, fusion and backend lowering</span></span></code></pre></div><p>This ordering prevents two historical failure modes:</p><ol><li>a codegen-only evaluator making semantic decisions after analysis; and</li><li>generated source or bitcode losing identities, generic substitutions, provenance, ownership facts, or target facts at a serialization boundary.</li></ol><h2 id="one-canonical-evaluator" tabindex="-1">One canonical evaluator <a class="header-anchor" href="#one-canonical-evaluator" aria-label="Permalink to &quot;One canonical evaluator&quot;">​</a></h2><p>Canonical CTFE operates on Vex HIR values and semantic IDs. It does not depend on <code>CodegenContext</code>, LLVM values, symbol names, or host pointers.</p><p>The value model covers target-aware fixed-width integers, bools, floats, text, typed aggregates, enums, sequences, insertion-ordered maps, references, reflection records, callable handles, and invocation-bound declaration plans.</p><p>Every evaluation runs with explicit context:</p><ul><li>source and expansion provenance;</li><li>exact generic type and const arguments;</li><li>selected target facts;</li><li>effect capabilities;</li><li>tracked environment/source inputs;</li><li>step, recursion, allocation, byte, collection, diagnostic, and expansion budgets.</li></ul><p>Required-comptime evaluation has only two terminal outcomes: a value/expansion or an error. It never silently asks codegen to execute the operation at runtime.</p><h2 id="effect-model" tabindex="-1">Effect model <a class="header-anchor" href="#effect-model" aria-label="Permalink to &quot;Effect model&quot;">​</a></h2><p>Functions are classified from their semantic body and reachable calls. The important distinction is whether an operation is legal and deterministic in the current compile-time context—not whether it comes from user code, std, or VexArch.</p><p>Pure arithmetic, exact reflection, deterministic collection operations, and tracked source/target queries may execute during CTFE. Runtime I/O, clocks, untracked external state, unsupported FFI, and runtime-only effects remain residual or are rejected by a strict boundary.</p><p>Effects are transitive. A wrapper around a runtime-only call is not considered pure merely because its own body contains no direct intrinsic.</p><h2 id="typed-staging-and-residualization" tabindex="-1">Typed staging and residualization <a class="header-anchor" href="#typed-staging-and-residualization" aria-label="Permalink to &quot;Typed staging and residualization&quot;">​</a></h2><p>Staging reports a typed result:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>StageResult&lt;T&gt; = Known(T) | Residual(ResidualHIR&lt;T&gt;) | Error(Diagnostic)</span></span></code></pre></div><p>The rewrite is transactional. A candidate is committed only after the known subgraph evaluates, the replacement is well typed, and consumer-visible semantics remain valid. Otherwise the original HIR is preserved or a strict boundary emits a diagnostic.</p><p>The accepted V2 frontier folds maximal known:</p><ul><li>primitive binary operations;</li><li>primitive unary operations;</li><li>casts; and</li><li>exact function/method call islands.</li></ul><p>Runtime-dependent parents remain ordinary HIR. Overloaded operators with an exact callable fact are excluded from the primitive path until canonical CTFE can dispatch that callable directly.</p><h2 id="collections-and-runtime-materialization" tabindex="-1">Collections and runtime materialization <a class="header-anchor" href="#collections-and-runtime-materialization" aria-label="Permalink to &quot;Collections and runtime materialization&quot;">​</a></h2><p>Compile-time allocations live in metered compiler storage. Host addresses are never Vex values and cannot escape.</p><p>When a known text, sequence, map, struct, or enum must enter runtime HIR, CTFE produces a typed construction recipe. That recipe is lowered through the ordinary ownership path:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>known CTFE value</span></span>
<span class="line"><span>  -&gt; typed materialization recipe</span></span>
<span class="line"><span>  -&gt; ordinary residual Vex HIR</span></span>
<span class="line"><span>  -&gt; borrow/move/drop validation</span></span>
<span class="line"><span>  -&gt; Valence/VUMM allocation and ownership selection</span></span>
<span class="line"><span>  -&gt; fusion and backend codegen</span></span></code></pre></div><p>There is no comptime-specific runtime allocator, object header, reference count, drop path, or hidden map representation.</p><h2 id="structural-declaration-expansion" tabindex="-1">Structural declaration expansion <a class="header-anchor" href="#structural-declaration-expansion" aria-label="Permalink to &quot;Structural declaration expansion&quot;">​</a></h2><p>An eager module generator is a top-level, non-generic, parameterless <code>const fn</code> returning <code>DeclSet</code>. Discovery creates a request containing its exact function identity, module owner, stable site key, lexical anchor, target, and budgets.</p><p>The generator returns compiler-owned structural plans. Expansion:</p><ol><li>reserves stable identity ranges for every invocation;</li><li>executes all generators under one cumulative metered session;</li><li>validates declaration roles, types, constraints, bodies, patterns, hygiene, and ownership;</li><li>remints generic type and const binders for the generated owner;</li><li>seals one combined source/generated scope and inference snapshot; and</li><li>exposes that same snapshot to compiler and tooling consumers.</li></ol><p>Generated native functions cross a dedicated typed boundary containing their signature, HIR body, provenance, and frozen inference result. They are not converted into source text, a synthetic parser tree, or a separate <code>.bc</code> module.</p><h2 id="fusion-and-vexarch" tabindex="-1">Fusion and VexArch <a class="header-anchor" href="#fusion-and-vexarch" aria-label="Permalink to &quot;Fusion and VexArch&quot;">​</a></h2><p>Known values are embedded into ordinary HIR before backend lowering. Residual user, std, and VexArch calls stay semantically visible in the same module and monomorphization graph. This allows normal inlining, reachability analysis, runtime fusion, ABI selection, and dead-code removal to operate across the boundary.</p><p>Comptime does not bypass VexArch. It can execute eligible VexArch <code>const fn</code> logic, but runtime VexArch work remains in the same fused runtime path as handwritten user code.</p><h2 id="persistent-cache" tabindex="-1">Persistent cache <a class="header-anchor" href="#persistent-cache" aria-label="Permalink to &quot;Persistent cache&quot;">​</a></h2><p>Persistent entries are semantic query results, not snapshots of host memory. Their keys include the compiler/language semantic version, target identity, generic instantiation, source dependencies, tracked environment/embed inputs, and effect policy.</p><p>Deserialization validates the entire recursive wire envelope. Current hard limits are:</p><table tabindex="0"><thead><tr><th>Limit</th><th style="text-align:right;">Value</th></tr></thead><tbody><tr><td>Semantic nodes</td><td style="text-align:right;">100,000</td></tr><tr><td>Semantic payload</td><td style="text-align:right;">64 MiB</td></tr><tr><td>Recursive depth</td><td style="text-align:right;">256</td></tr></tbody></table><p>The stack-safe validator meters value nodes, type arguments, nominal fields, and promoted projections. Corrupt, stale, too-deep, oversized, or target-incompatible entries become cache misses.</p><p>Invocation-bound declaration values and compiler-storage addresses are never published as ordinary persistent constants.</p><h2 id="target-portability" tabindex="-1">Target portability <a class="header-anchor" href="#target-portability" aria-label="Permalink to &quot;Target portability&quot;">​</a></h2><p>Layout, pointer width, integer domains, and target-specific intrinsic choices come from the exact semantic target key. Backend lowering checks that its LLVM target agrees with that key and fails closed on drift.</p><p>For example, PDEP/PEXT may select LLVM x86 BMI2 intrinsics only for an exact <code>x86_64 +bmi2</code> target. Generic x86_64, i686, AArch64, and PowerPC64 use the deterministic software lowering. A host CPU feature cannot leak into a cross-compiled artifact.</p><h2 id="consumer-parity" tabindex="-1">Consumer parity <a class="header-anchor" href="#consumer-parity" aria-label="Permalink to &quot;Consumer parity&quot;">​</a></h2><p>Compiler, diagnostics-only analysis, lint, and LSP use the same expansion and staging queries. The parity harness checks:</p><ul><li>known/residual/error classification;</li><li>values and diagnostics;</li><li>generated identity and provenance;</li><li>target-sensitive behavior;</li><li>no-artifact analysis without LLVM;</li><li>native lowering of the same sealed HIR.</li></ul><p>The current V2 closure gates include full HIR and native suites, architecture invariants, HIR/CLI parity, persistent-cache envelope tests, and a semantic performance fixture.</p><h2 id="performance-baseline" tabindex="-1">Performance baseline <a class="header-anchor" href="#performance-baseline" aria-label="Permalink to &quot;Performance baseline&quot;">​</a></h2><p>The release staging benchmark separates analysis overhead from known-root evaluation:</p><table tabindex="0"><thead><tr><th>Workload</th><th style="text-align:right;">2026-08-14 median</th><th style="text-align:right;">Throughput</th></tr></thead><tbody><tr><td>128 no-call functions</td><td style="text-align:right;">1.800 ms</td><td style="text-align:right;">71.1K functions/s</td></tr><tr><td>64 literal bindings</td><td style="text-align:right;">102.6 µs</td><td style="text-align:right;">624K bindings/s</td></tr><tr><td>64 cold known roots</td><td style="text-align:right;">1.809 ms</td><td style="text-align:right;">35.4K roots/s</td></tr><tr><td>64 warm known roots</td><td style="text-align:right;">1.506 ms</td><td style="text-align:right;">42.5K roots/s</td></tr></tbody></table><p>These numbers are a regression baseline, not a universal build-time promise. Package-scale longitudinal SLOs and further acceleration should follow profiles that identify a dominant cost.</p><h2 id="deliberate-post-v2-extensions" tabindex="-1">Deliberate post-V2 extensions <a class="header-anchor" href="#deliberate-post-v2-extensions" aria-label="Permalink to &quot;Deliberate post-V2 extensions&quot;">​</a></h2><p>The architecture keeps the following out of the accepted V2 contract:</p><ul><li>cyclic persistent values;</li><li>arbitrary boolean constraint algebra;</li><li>unknown-slot aggregate residual graphs;</li><li>automatic production-wide <code>ApplyKnown</code> rollout;</li><li>unproven scalable/GPU/foreign vector ABI layouts;</li><li>token/procedural macro compatibility layers.</li></ul><p>Future work must extend the canonical identity, effect, ownership, target, cache, and parity contracts. It must not add a second evaluator or a codegen-only semantic fallback.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/guide/advanced/comptime">Compile-Time Evaluation</a></li><li><a href="/docs/guide/advanced/comptime-declarations">Structural Declaration Generation</a></li><li><a href="/docs/architecture/compiler-pipeline">Compiler Pipeline</a></li><li><a href="/docs/architecture/runtime-architecture">Runtime Architecture</a></li><li><a href="/docs/guide/memory/vumm">VUMM</a></li></ul>`,59)])])}const m=a(s,[["render",r]]);export{h as __pageData,m as default};
